import{_ as r,o as e,c as o,a2 as a}from"./chunks/framework.Buc7gXeZ.js";const c=JSON.parse('{"title":"资源收录与投稿标准","description":"MetaFusion 媒体资源收录流程、文件格式规范与审核机制。","frontmatter":{"title":"资源收录与投稿标准","description":"MetaFusion 媒体资源收录流程、文件格式规范与审核机制。","order":21,"group":"guide"},"headers":[],"relativePath":"contribute-guide.md","filePath":"contribute-guide.md"}'),d={name:"contribute-guide.md"};function i(n,t,s,l,h,g){return e(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="资源收录与投稿标准" tabindex="-1">资源收录与投稿标准 <a class="header-anchor" href="#资源收录与投稿标准" aria-label="Permalink to &quot;资源收录与投稿标准&quot;">​</a></h1><p>为了保障全站资源的长期可用性与播放体验，MetaFusion 对投稿收录的媒体资源与元数据制定了以下标准。</p><hr><h2 id="_1-投稿流程" tabindex="-1">1. 投稿流程 <a class="header-anchor" href="#_1-投稿流程" aria-label="Permalink to &quot;1. 投稿流程&quot;">​</a></h2><ol><li><strong>查重确认</strong>：在提交前，请先在搜索栏进行检索，确认平台尚未收录该发行版本，避免重复录入。</li><li><strong>填写元数据</strong>：在 <a href="/docs/contribute">投稿中心</a> 填写作品标题、发行日期、分类标签及参考来源。</li><li><strong>上传物理资源</strong>：选择本地文件分片直传至对象存储，支持断点续传。</li><li><strong>提交审核</strong>：提交后条目进入审核队列，由考据员审核通过后全站呈现。</li></ol><hr><h2 id="_2-媒体格式建议" tabindex="-1">2. 媒体格式建议 <a class="header-anchor" href="#_2-媒体格式建议" aria-label="Permalink to &quot;2. 媒体格式建议&quot;">​</a></h2><table tabindex="0"><thead><tr><th>媒介类型</th><th>推荐格式</th><th>说明</th></tr></thead><tbody><tr><td><strong>无损音频</strong></td><td>FLAC, ALAC, WAV (16/24-bit)</td><td>平台会自动转码生成 320kbps 预览流与波形图，原档完好保留</td></tr><tr><td><strong>有损音频</strong></td><td>MP3 (320kbps), AAC (256kbps+)</td><td>适合体积极致轻量化的原声或广播剧</td></tr><tr><td><strong>视频影像</strong></td><td>MP4 (H.264/HEVC), MKV</td><td>平台会自动切片生成多码率 HLS 流与雪碧图预览</td></tr><tr><td><strong>电子书刊</strong></td><td>EPUB, PDF, CBZ/CBR</td><td>适合漫画画集与小说文献</td></tr><tr><td><strong>封面图片</strong></td><td>JPG, PNG, WebP (建议分辨率 ≥ 1000x1000)</td><td>保持高清方图，无多余水印</td></tr></tbody></table><hr><h2 id="_3-审核状态说明" tabindex="-1">3. 审核状态说明 <a class="header-anchor" href="#_3-审核状态说明" aria-label="Permalink to &quot;3. 审核状态说明&quot;">​</a></h2><ul><li><strong>待审核 (Pending)</strong>：新提交的资源已入库，等待考据员核验元数据与文件完整性。</li><li><strong>已通过 (Approved)</strong>：核验通过，条目对全站用户公开，出现在搜索与推荐列表。</li><li><strong>需修正 (Needs Revision)</strong>：考据员在审核意见中指出缺失信息（如缺少来源、曲目顺序颠倒等），贡献者可在编辑后重新提交。</li></ul><hr><h2 id="_4-贡献者荣誉与历史" tabindex="-1">4. 贡献者荣誉与历史 <a class="header-anchor" href="#_4-贡献者荣誉与历史" aria-label="Permalink to &quot;4. 贡献者荣誉与历史&quot;">​</a></h2><ul><li>用户的每一次有效贡献都会记录在个人主页的 <strong>“贡献历史”</strong> 中。</li><li>高质量的持续贡献者可申请成为社区 <strong>考据员 (Archivist)</strong>，获得直接审核与词条锁定的权限。</li></ul>',14)])])}const _=r(d,[["render",i]]);export{c as __pageData,_ as default};
